import{z as i,x as B,o as A,c as p,q as l,j as o,D as t,d as E,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"评测的统计功效","description":"","frontmatter":{"title":"评测的统计功效","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ef-statistical-power.md","filePath":"llm/ef-statistical-power.md","lastUpdated":1791063341000}'),d={name:"llm/ef-statistical-power.md"};function m(h,a,D,C,f,c){const r=B("Mermaid");return A(),p("div",null,[a[2]||(a[2]=l('<h1 id="评测的统计功效" tabindex="-1">评测的统计功效 <a class="header-anchor" href="#评测的统计功效" aria-label="Permalink to &quot;评测的统计功效&quot;">​</a></h1><div class="epigraph"><p>名次的资格不是跑出来的，是设计出来的：效应量、样本量、配对方式与多重比较，先于第一次评测就定了几分之差才算数。</p><footer>—— 据 Dietterich 1998、Rodriguez 等 2021、Benavoli 等 2017 与 bootstrap 传统整理</footer></div><p><a href="/llm/ef-newtask-design">上一课</a>把卷子按区分度设计完。本课回答另一半问题：跑多少题、多少票，才配让一个名次说话。<a href="/llm/eval-variance-seed">种子与方差课</a>拆过噪声来源 \\(S(\\theta,\\xi)\\) 并规定重复方式；<a href="/llm/aeval-crossmodel-pitfalls">跨模型陷阱课</a>给过「换序、配对、区间」四件套。本课往前挪一步，写<strong>功效分析</strong>：在花算力之前算出最小可检测差与所需样本量，并给名次变化立统计资格线。组合课的每层预算都从这里出发。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>评测结论的失效大多是功效失效：两张卷各跑一次，A 高 B 一分，结论「A 更强」——这一分可能落在题目抽样或解码种子的噪声里。三种典型错误。一是<strong>样本量与声明不匹配</strong>：要在 2 个点上分辨模型，八百题的卷子根本不带这么窄的区间。二是<strong>配对缺失</strong>：两模型各用随机一半题，题目难度差被算进模型差；同一批题的配对设计能消掉这一项。三是<strong>多重比较没人管</strong>：扫二十个基准挑最好的报，星座对齐式的显著几乎必然出现——在 \\(\\alpha=0.05\\) 下扫二十次，期望假阳性约一次起。<span class="marginnote">显著性水平 \\(\\alpha=0.05\\) 可以读成一句承诺：「我允许自己有 5% 的概率把『其实没差别』误报成『有差别』」。关键在于它是跑数据<strong>之前</strong>定下的误报预算——先定预算再看数据，与跑完数据再挑一个好看的说法，是科学与作弊的分界线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先声明<strong>最小可检测差</strong> \\(\\delta\\)：产品或论文真正在乎的差距是多大？胜率比较按符号检验的样本量近似</p> \\[n \\;\\approx\\; \\frac{(z_{\\alpha/2}+z_{\\beta})^{2}\\; p(1-p)}{\\delta^{2}}, \\]<p>\\(p\\) 是胜率基线（约 0.5 最保守），\\(\\alpha\\) 是显著性水平，\\(1-\\beta\\) 是功效。连续分数用配对差值的 \\(t\\) 检验或置换检验，区间用对题目的 bootstrap：重抽题不重抽模型，得分的分布就是题目抽样不确定度。<strong>配对是默认</strong>：同一批题、同一张种子表跑两个模型，逐题差值消掉题目难度项。<strong>多重比较</strong>：门禁若同时看 \\(m\\) 个指标，用 Holm 或 Bonferroni 把每次的 \\(\\alpha\\) 收紧，<span class="marginnote">Bonferroni 校正简单到一句话：同时比较 \\(m\\) 项，就把每次的 \\(\\alpha\\) 除以 \\(m\\)。比如同时比 20 个指标，每次的门槛就从 0.05 收到 \\(0.05/20=0.0025\\)——单项更难「显著」，换来的是整族比较的误报率仍被压在 5% 附近，扫榜挑好看数字的路被堵死。</span>或把一族比较报成联合声明。<strong>省样本量</strong>靠设计而非硬跑：IRT 类方法按题目信息量选题，Rodriguez 等显示按信息量加权或自适应选题可用少得多的题估出同样的名次。</p>',9)),(A(),o(n,null,{default:t(()=>[s(r,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20CL%5B%22%E5%A3%B0%E6%98%8E%EF%BC%9A%E5%9C%A8%E4%B9%8E%E5%A4%9A%E5%A4%A7%E7%9A%84%E5%B7%AE%20%CE%B4%22%5D%20--%3E%20PW%5B%22%E5%8A%9F%E6%95%88%E5%88%86%E6%9E%90%E5%AE%9A%20n%20%E4%B8%8E%E9%85%8D%E5%AF%B9%E6%96%B9%E5%BC%8F%22%5D%0A%20%20PW%20--%3E%20RUN%5B%22%E5%90%8C%E9%A2%98%E5%90%8C%E7%A7%8D%E5%AD%90%E8%A1%A8%E9%85%8D%E5%AF%B9%E8%B7%91%22%5D%0A%20%20RUN%20--%3E%20CI%5B%22bootstrap%20%2F%20%E7%BD%AE%E6%8D%A2%E6%A3%80%E9%AA%8C%E5%87%BA%E5%8C%BA%E9%97%B4%22%5D%0A%20%20CI%20--%3E%20MC%7B%22%E5%90%8C%E6%97%B6%E6%AF%94%20m%20%E9%A1%B9%3F%22%7D%0A%20%20MC%20--%3E%7C%22%E6%98%AF%22%7C%20ADJ%5B%22Holm%20%2F%20Bonferroni%20%E6%A0%A1%E6%AD%A3%22%5D%0A%20%20MC%20--%3E%7C%22%E5%90%A6%22%7C%20DEC%5B%22%E5%8C%BA%E9%97%B4%E5%A4%96%E6%89%8D%E8%B0%88%E5%90%8D%E6%AC%A1%E5%8F%98%E5%8C%96%22%5D%0A%20%20ADJ%20--%3E%20DEC%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("为什么配对能省一个数量级的题：不配对时方差是题目方差加解码方差，配对后只剩差值的方差，而同一道题上两个模型的得分高度相关，相关越高压掉越多。功效公式的机制在平方项：\\(\\delta\\) 收窄一半，\\(n\\) 要翻四倍——「从差 5 个点变成在乎 2 个点」不是多跑一点，是换一个量级的预算。多次比较的机制在选择性：只报二十次比较里最显著的一次，等于把阈值私改成了 \\(\\alpha/20\\) 的别名；校正不是仪式，是把选择性买回来。区间还有个不对称用法："),e("strong",null,"区间内不结论，区间外才行动"),E("——评测的产出从「谁第一」变成「谁能排除谁」，这与整个课程的区间纪律一致。")],-1)),(A(),o(n,null,{default:t(()=>[s(r,{id:"mermaid-30",class:"mermaid",graph:"flowchart%20TD%0A%20%20NP%5B%22%E4%B8%8D%E9%85%8D%E5%AF%B9%3A%20%E4%B8%A4%E6%A8%A1%E5%9E%8B%E5%90%84%E8%B7%91%E9%9A%8F%E6%9C%BA%E4%B8%80%E5%8D%8A%E9%A2%98%22%5D%20--%3E%20V1%5B%22%E8%A7%82%E6%B5%8B%E5%B7%AE%20%3D%20%E6%A8%A1%E5%9E%8B%E5%B7%AE%3Cbr%2F%3E%E5%8A%A0%20%E9%A2%98%E7%9B%AE%E9%9A%BE%E5%BA%A6%E5%B7%AE%20%E5%8A%A0%20%E8%A7%A3%E7%A0%81%E5%99%AA%E5%A3%B0%22%5D%0A%20%20P%5B%22%E9%85%8D%E5%AF%B9%3A%20%E5%90%8C%E9%A2%98%E5%90%8C%E7%A7%8D%E5%AD%90%E8%A1%A8%22%5D%20--%3E%20V2%5B%22%E9%80%90%E9%A2%98%E7%9B%B8%E5%87%8F%E5%90%8E%3Cbr%2F%3E%E9%A2%98%E7%9B%AE%E9%9A%BE%E5%BA%A6%E9%A1%B9%E8%A2%AB%E6%B6%88%E6%8E%89%22%5D%0A%20%20V1%20--%3E%20W%5B%22%E6%96%B9%E5%B7%AE%E5%A4%A7%3A%20%E5%8C%BA%E9%97%B4%E5%AE%BD%3Cbr%2F%3E%E8%A6%81%E6%9B%B4%E5%A4%9A%E9%A2%98%E6%89%8D%E8%83%BD%E5%8E%8B%E7%AA%84%22%5D%0A%20%20V2%20--%3E%20N%5B%22%E6%96%B9%E5%B7%AE%E5%B0%8F%3A%20%E5%8C%BA%E9%97%B4%E7%AA%84%3Cbr%2F%3E%E4%B8%A4%E6%A8%A1%E5%9E%8B%E8%B6%8A%E7%9B%B8%E5%85%B3%20%E5%8E%8B%E6%8E%89%E8%B6%8A%E5%A4%9A%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">量级直觉：\\(p\\approx 0.5\\)、\\(\\alpha=0.05\\)、功效 0.8 时，检测 5 个点的胜率差约需八百对上下；收窄到 2 个点，就要五千对往上。八百题的卷子上吵 1 个点的名次，是在吵噪声。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>统计显著不等于工程显著：五万票上 0.3 个点的胜率差可以显著到没有意义，反过来工程在乎的差也可能因预算测不显著—— \\(\\delta\\) 该由决策成本定，不是由算力定。功效分析的前提是方差估计可信：小题集上 bootstrap 区间本身偏窄，先用历史方差或文献口径定先验。IRT 与自适应选题假设单维性，多维卷子上「高效」的子集会在构念上偏科，主尺慎用。<span class="marginnote">初学者容易把「统计显著」当成「重要」。显著只回答「这个差是不是巧合」：五万票上 0.3 个点的差可以显著到毫无意义——差异是真的，但小到用户感知不到；而真正要紧的 2 个点差也可能因预算不够而测不出显著。重不重要由 \\(\\delta\\) 与决策成本回答，不由 p 值回答。</span>最后，配对设计锁死了题集，公共题集用久了要按<a href="/llm/live-benchmarks">动态基准</a>的口径补新题，功效账要连新题的预算一起算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>先定最小可检测差 \\(\\delta\\) 与 \\(\\alpha\\)、功效，再定 \\(n\\)；样本量是设计产物不是剩多少跑多少。</li><li>配对是默认：同题同种子表，逐题差值消掉题目方差。</li><li>区间用对题目的 bootstrap 或置换检验；同时比多项做多重比较校正。</li><li>区间内不下名次结论；评测产出是「能排除谁」，不是「谁第一」。</li><li>出处：Dietterich 1998；Rodriguez 等 2021（IRT 与题目信息量）；Benavoli 等 2017（贝叶斯比较）；Efron 与 Tibshirani 的 bootstrap，按本课程整理。</li></ul>',5))])}const _=i(d,[["render",m]]);export{b as __pageData,_ as default};
